/*
 * A050826  Odd numbers in the sequence generated by
 *          a(n)=a(a(n-2))+a(n-a(n-2)).
 * https://oeis.org/A050826
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = a(a(n-2)) + a(n - a(n-2)), a(1)=1, a(2)=1 The function
 *            returns the nth odd value of that sequence (OEIS A050826)
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* The full sequence (1‑based, b[0] unused).  Allocated dynamically. */
static seq_t *b = NULL;
static size_t b_cap = 0;   /* capacity of the b array (excluding index 0) */
static size_t b_len = 0;   /* highest index currently computed */

/* Odd values of the sequence, also 1‑based. */
static seq_t *odd = NULL;
static size_t odds_cap = 0; /* capacity of the odd array (excluding index 0) */
static size_t odds_len = 0; /* number of odd values stored */

/* Ensure b has room for indices up to ‘need’ (inclusive). */
static void ensure_b_capacity(size_t need)
{
    if (need <= b_cap) return;
    size_t new_cap = b_cap ? b_cap << 1 : 1;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(b, (new_cap + 1) * sizeof(seq_t));
    b = tmp;
    b_cap = new_cap;
}

/* Ensure odd has room for indices up to ‘need’ (inclusive). */
static void ensure_odds_capacity(size_t need)
{
    if (need <= odds_cap) return;
    size_t new_cap = odds_cap ? odds_cap << 1 : 1;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(odd, (new_cap + 1) * sizeof(seq_t));
    odd = tmp;
    odds_cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* undefined but safe fallback */

    /* One‑time initialization on first call. */
    if (odd == NULL) {
        /* Allocate enough space for indices 0,1,2.  We keep index 0 unused. */
        ensure_b_capacity(2);
        b[1] = (seq_t)1;
        b[2] = (seq_t)1;
        b_len = 2;

        ensure_odds_capacity(2);
        odd[1] = b[1];
        odd[2] = b[2];
        odds_len = 2;
    }

    /* Generate terms until we have produced at least 'n' odd values. */
    while (odds_len < n) {
        /* Next index to compute. */
        idx_t next_i = (idx_t)(b_len + 1);
        size_t ni = (size_t)next_i;  /* size_t for array indexing */

        /* Indices required by the recurrence. */
        idx_t k1 = (idx_t)b[ni - 2];           /* a(next_i-2) */
        idx_t k2 = next_i - k1;                /* next_i - a(next_i-2) */

        /* Retrieve terms. */
        seq_t v1 = b[(size_t)k1];
        seq_t v2 = b[(size_t)k2];

        /* Compute b(next_i). */
        seq_t bi = v1 + v2;

        /* Store the new term. */
        ensure_b_capacity(ni);
        b[ni] = bi;
        b_len = ni;

        /* If the new term is odd, record it. */
        if ((bi & (seq_t)1) != (seq_t)0) {
            ensure_odds_capacity(odds_len + 1);
            odd[odds_len + 1] = bi;
            odds_len++;
        }
    }

    /* Return the requested odd value. */
    return odd[n];
}
